(() => {
  'use strict';
  const ui=window.KaretaPageUI;
  const api=window.KaretaClientCabinetApi;
  const firstVehicleFlow=window.KaretaFirstVehicleFlow;
  if(!ui||!api||!firstVehicleFlow) throw new Error('Client cabinet dependencies are required');
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>new Intl.NumberFormat('ru-RU').format(Number(v||0))+' ₸';
  let data=null;
  let sessionEpoch=0;
  let serviceVehicleId='';
  const icon=new Proxy(Object.create(null),{get:(_target,key)=>window.KaretaUIIcons?.svg?.(String(key))||''});
  const brandLogo=brand=>window.KaretaVisualAssets?.brandLogo?.(brand)||'';
  const vehicleImage=brand=>window.KaretaVisualAssets?.vehicleImage?.(brand)||'';
  const back=()=>'<a class="k-cabinet-back" href="#/cabinet" data-route-link="cabinet">Назад в кабинет</a>';
  function shell(title,text,body){const master=currentRole()==='master';if(master)return `<section class="k-page k-client-cabinet-page k-master-page k-master-surface-page">${ui.masterPageHeader(title,text,{eyebrow:'НАСТРОЙКИ МАСТЕРА',actions:'<a class="k-btn k-btn-secondary k-master-page-header__back" href="#/cabinet" data-route-link="cabinet">Назад</a>'})}${body}</section>`;return `<section class="k-page k-client-cabinet-page"><header class="k-client-subhead">${back()}<h1>${title}</h1><p>${text}</p></header>${body}</section>`;}
  function garageShell(d,body){
    const vehicles=d?.vehicles||[],orders=d?.orders||[],reminders=d?.reminders||[];
    const due=reminders.filter(r=>['overdue','soon'].includes(String(r.level||''))).length;
    const repairs=orders.length;
    return `<section class="k-page k-client-cabinet-page k-garage-page-r77 k-flow-primary-page" data-page="client-garage">
      <header class="k-garage-head-r77"><div class="k-garage-head-r77__copy"><small>МОЙ ГАРАЖ</small><h1>Автомобили</h1><p>Паспорт автомобиля, обслуживание, ремонты и сроки — в одном рабочем пространстве.</p></div><button class="k-garage-add-r77" type="button" data-garage-add-vehicle><span aria-hidden="true">${icon.plus}</span> Добавить авто</button></header>
      <section class="k-garage-summary-r77" aria-label="Сводка гаража"><article><b>${vehicles.length}</b><span>автомобилей</span></article><article><b>${repairs}</b><span>записей ремонта</span></article><article class="${due?'has-alert':''}"><b>${due}</b><span>требуют внимания</span></article></section>
      ${body}
    </section>`;
  }
  function card(key,title,text,href){return `<a class="k-client-cabinet-card" href="${href}"><span class="k-client-card-icon">${icon[key]}</span><span class="k-client-card-copy"><b>${title}</b><small>${text}</small></span><i class="k-client-card-arrow" aria-hidden="true">${icon.chevronRight}</i></a>`;}
  function windowCard(key,title,text,kind,href=''){return `<a class="k-client-cabinet-card" href="${href||'#'}" data-account-window="${kind}"><span class="k-client-card-icon">${icon[key]}</span><span class="k-client-card-copy"><b>${title}</b><small>${text}</small></span><i class="k-client-card-arrow" aria-hidden="true">${icon.chevronRight}</i></a>`;}
  function currentRole(){return String(window.KaretaNavigationCore?.interfaceRole?.()||window.KaretaRoleAccess?.currentRole?.()||window.KaretaNext?.state?.user?.role||'client').toLowerCase();}
  function openClientAccountWindow(kind){const accountWindow=window.KaretaAccountWindow;if(accountWindow?.open)return accountWindow.open(kind);try{sessionStorage.setItem('kareta.account.window.pending',String(kind||''));}catch(_e){}if(String(location.hash||'')!=='#/cabinet')location.hash='#/cabinet';return false;}
  function isClientCabinetRole(){return currentRole()==='client';}
  function guardedClientPage(title){const role=currentRole();const target=role==='master'?'#/master':role==='sto'?'#/sto':role==='seller'?'#/seller':'#/cabinet';return `<section class="k-page k-client-cabinet-page"><div class="k-empty-card"><h1>${esc(title)}</h1><p>Этот раздел относится к кабинету клиента и недоступен для роли «${esc(role)}».</p><a class="k-btn k-btn-primary" href="${target}">Открыть свой кабинет</a></div></section>`;}
  function staffCard(iconName,title,text,href,meta=''){return `<a class="k-staff-cabinet-card" href="${href}"><span class="k-staff-cabinet-icon" aria-hidden="true">${icon[iconName]}</span><span class="k-staff-cabinet-copy"><b>${title}</b><small>${text}</small>${meta?`<em>${meta}</em>`:''}</span><span class="k-staff-cabinet-arrow" aria-hidden="true">${icon.chevronRight}</span></a>`;}
  function renderMasterCabinet(){return `<section class="k-page k-master-page k-master-surface-page k-staff-cabinet k-staff-cabinet--master" data-page="cabinet" data-cabinet-role="master"><header class="k-staff-cabinet-head k-master-page-header"><div class="k-master-page-header__copy"><small>АККАУНТ МАСТЕРА</small><h1>Профиль и настройки</h1><p>Профиль, тариф, публикации и настройки рабочего аккаунта.</p></div></header><div class="k-staff-cabinet-grid">${staffCard('user','Публичный профиль','Карточка мастера, специализация и репутация','#/master/profile')}${staffCard('finance','Тариф и лимиты','Приёмы, заявки, открытые ремонты и доступные возможности','#/cabinet/tariff','Контроль загрузки')}${staffCard('community','Мои публикации','Выполненные работы, новости и черновики','#/master/wall')}${staffCard('settings','Настройки','Рабочий экран, интерфейс и каналы связи','#/cabinet/settings')}</div><section class="k-staff-cabinet-summary"><div><b id="k-master-cabinet-active">—</b><span>активных заказов</span></div><div><b id="k-master-cabinet-done">—</b><span>выполнено</span></div><div><b id="k-master-cabinet-rating">—</b><span>рейтинг</span></div><div><b id="k-master-cabinet-revenue">—</b><span>выручка</span></div></section></section>`;}
  function renderStoCabinet(){return `<section class="k-page k-staff-cabinet k-staff-cabinet--sto" data-page="cabinet" data-cabinet-role="sto"><header class="k-staff-cabinet-head"><div><span>КАБИНЕТ СТО</span><h1>Управление автосервисом</h1><p>Мастера, заказы, услуги, выручка, KPI и настройки конкретного СТО.</p></div><a class="k-btn k-btn-primary" href="#/sto">Открыть панель СТО</a></header><div class="k-staff-cabinet-grid">${staffCard('store','Панель СТО','Выручка, загрузка, очередь и ключевые показатели','#/sto')}${staffCard('masters','Мои мастера','Команда СТО, KPI и история работ','#/masters')}${staffCard('orders','Заказы СТО','Все заявки и ремонты вашего сервиса','#/orders')}${staffCard('services','Услуги СТО','Собственные предложения и цены','#/services/manage')}${staffCard('chats','Чаты','Клиенты, мастера и рабочие обсуждения','#/chats')}${staffCard('user','Настройки СТО','Профиль, адрес, график и контактные данные','#/cabinet/settings')}</div></section>`;}
  function renderSellerCabinet(){return `<section class="k-page k-staff-cabinet k-staff-cabinet--seller" data-page="cabinet" data-cabinet-role="seller"><header class="k-staff-cabinet-head"><div><span>КАБИНЕТ ПРОДАВЦА</span><h1>Товары, заказы и продажи</h1><p>Управляйте каталогом запчастей, запросами покупателей, заказами, чатами и настройками магазина.</p></div><a class="k-btn k-btn-primary" href="#/seller">Открыть панель продавца</a></header><div class="k-staff-cabinet-grid">${staffCard('store','Панель продавца','Продажи, заявки, остатки и ключевые показатели','#/seller')}${staffCard('parts','Мои товары','Каталог, цены, наличие и карточки запчастей','#/seller/products')}${staffCard('orders','Заказы','Запросы покупателей и обработка заказов','#/seller/orders')}${staffCard('community','Сообщество','Публикации, акции и обновления магазина','#/works')}${staffCard('chats','Чаты','Переписка с клиентами и СТО','#/chats')}${staffCard('user','Профиль магазина','Профиль, контакты, доставка и возврат','#/seller')}</div></section>`;}
  function renderClientCabinet(){return `<section class="k-page k-client-cabinet k-client-account-native" data-page="cabinet" data-native-ui="client-account"><header class="k-client-account-head"><div><span>ЛИЧНЫЙ АККАУНТ</span><h1>Мой аккаунт</h1><p>Автомобили и история остаются рабочими разделами. Профиль, документы, тариф и настройки открываются большими окнами поверх аккаунта.</p></div><div class="k-client-account-head__actions"><button class="k-btn k-btn-secondary" type="button" data-account-window="notifications">Уведомления</button><a class="k-btn k-btn-primary" href="#/profile">Публичный профиль</a></div></header><div id="k-client-profile-host" class="k-social-profile-host k-client-account-profile" aria-live="polite"><div class="k-cabinet-loading">Загрузка профиля…</div></div><section class="k-client-account-overview" aria-label="Сводка аккаунта"><article><span>Автомобили</span><b id="k-client-account-vehicles">—</b><small>в вашем гараже</small></article><article><span>Активные ремонты</span><b id="k-client-account-active">—</b><small>сейчас в работе</small></article><article><span>Требует внимания</span><b id="k-client-account-reminders">—</b><small>сервисных напоминаний</small></article><article><span>Завершено</span><b id="k-client-account-completed">—</b><small>подтверждённых заказов</small></article></section><div id="k-client-vehicles-host" class="k-client-vehicles-host" aria-live="polite"></div><section class="k-client-account-sections k-client-account-sections-r79"><header><span>РАЗДЕЛЫ АККАУНТА</span><h2>Управление через окна</h2><p>Гараж и история — рабочие пространства. Остальные действия не уводят со страницы аккаунта.</p></header><div class="k-client-cabinet-grid">${card('garage','Мой гараж','Автомобили, цифровые паспорта и сервисные книжки','#/cabinet/garage')}${windowCard('data','Профиль','Имя, телефон, город и личные данные','profile','#/cabinet/data')}${card('history','История обслуживания','Заявки, ремонты и расходы по автомобилям','#/cabinet/history')}${windowCard('documents','Документы','Страховки, техосмотр, гарантии и сроки','documents','#/cabinet/documents')}${card('promo','Мои предложения','Персональные акции и полезные возможности','#/cabinet/promotions')}${windowCard('tariff','Тариф','Лимиты аккаунта и возможности KARETA PRO','tariff','#/cabinet/tariff')}${windowCard('settings','Уведомления','События, ремонты, документы и акции','notifications','#/notifications')}${windowCard('settings','Безопасность','Сессия, контекст и выход из аккаунта','security')}${windowCard('settings','Интерфейс','Вид меню и мобильные параметры','interface','#/cabinet/settings')}</div></section></section>`;}
  function renderCabinet(){const role=currentRole();if(role==='client')return renderClientCabinet();if(role==='master')return renderMasterCabinet();if(role==='sto')return renderStoCabinet();if(role==='seller')return renderSellerCabinet();return guardedClientPage('Кабинет клиента');}
  const loading=(title,text)=>shell(title,text,'<div class="k-cabinet-loading">Загрузка данных…</div>');
  const renderGarage=()=>isClientCabinetRole()?`<section class="k-page k-client-cabinet-page k-garage-page-r77 k-flow-primary-page"><div class="k-garage-loading-r77"><span></span><span></span><span></span></div></section>`:guardedClientPage('Мой гараж');
  const renderData=()=>isClientCabinetRole()?loading('Мои данные','Контактные данные владельца аккаунта.'):guardedClientPage('Мои данные');
  const renderHistory=()=>isClientCabinetRole()?loading('История','Заявки, выполненные работы и расходы.'):guardedClientPage('История');
  const renderDocuments=()=>isClientCabinetRole()?loading('Документы','Документы ваших автомобилей и сроки действия.'):guardedClientPage('Документы');
  const renderPromos=()=>isClientCabinetRole()?loading('Мои акции','Предложения, доступные вашему аккаунту.'):guardedClientPage('Мои акции');
  const renderSettings=()=>isClientCabinetRole()?loading('Настройки','Настройте уведомления и мобильный интерфейс.'):renderStaffSettings();
  async function load(force=false){if(data&&!force)return data;const epoch=sessionEpoch;const r=await api.get(force?{cacheTtlMs:0}:{});if(epoch!==sessionEpoch)throw new Error('session_changed');if(!r.ok)throw new Error(r.payload?.message||'Не удалось загрузить кабинет');data=r.payload?.data||{};return data;}
  function replace(html){const node=document.querySelector('#k-page-outlet .k-client-cabinet-page');if(node)node.outerHTML=html;}
  function profileInitials(user){const source=String(user?.name||user?.initials||'Клиент').trim();return source.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'К';}
  function memberSince(value){if(!value)return 'Дата регистрации не указана';const d=new Date(String(value).replace(' ','T'));if(Number.isNaN(d.getTime()))return 'Аккаунт клиента';return `На KARETA.KZ с ${d.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}`;}
  function renderSocialProfile(d){const u=d.user||{},m=d.metrics||{};const avatar=String(u.avatarUrl||u.avatar_url||'').trim();const bio=String(u.bio||'').trim();return `<article class="k-social-profile-card k-social-profile-card-r79" data-client-profile-card><div class="k-social-profile-cover"><span>KARETA.KZ</span></div><div class="k-social-profile-main"><div class="k-social-profile-avatar-wrap"><div class="k-social-profile-avatar">${avatar?`<img src="${esc(avatar)}" alt="Аватар пользователя">`:`<span>${esc(profileInitials(u))}</span>`}</div></div><div class="k-social-profile-identity"><div class="k-social-profile-title"><div><span class="k-profile-role">КЛИЕНТ KARETA.KZ</span><h1>${esc(u.name||'Укажите имя')}</h1><p>${esc([u.city,memberSince(u.created_at||u.createdAt)].filter(Boolean).join(' · '))}</p></div><button class="k-btn k-btn-primary" type="button" data-account-window="profile">Редактировать профиль</button></div>${bio?`<p class="k-social-profile-bio">${esc(bio)}</p>`:''}<div class="k-social-profile-stats"><span><b>${Number(m.vehicles||0)}</b><small>авто</small></span><span><b>${Number(m.activeOrders||0)}</b><small>в работе</small></span><span><b>${Number(m.promotions||0)}</b><small>акции</small></span></div></div></div></article>`;}
  function cabinetVehicleTitle(v){return String(v.title||[v.brand,v.model].filter(Boolean).join(' ')||'Автомобиль');}
  const vehicleBodyLabel=value=>({sedan:'Седан',suv:'Кроссовер',hatchback:'Хэтчбек',wagon:'Универсал',coupe:'Купе',minivan:'Минивэн',pickup:'Пикап',other:'Другой'}[String(value||'')]||String(value||''));
  function cabinetVehicleCard(v){const title=cabinetVehicleTitle(v),car=vehicleImage(v.brand),logo=brandLogo(v.brand),fallback=esc((v.brand||'AUTO').slice(0,2).toUpperCase());return `<article class="k-account-vehicle-card"><div class="k-account-vehicle-visual">${car?`<img class="k-account-vehicle-image" src="${esc(car)}" alt="${esc(title)}" loading="lazy" decoding="async">`:''}<span class="k-account-vehicle-brand">${logo?`<img class="k-account-vehicle-brand-logo" src="${esc(logo)}" alt="${esc(v.brand||'Марка')}">`:fallback}</span><div class="k-account-vehicle-road" aria-hidden="true"></div></div><div class="k-account-vehicle-body"><div class="k-account-vehicle-head"><div><span>${esc(v.year_label||v.year||'Год не указан')}</span><h3>${esc(title)}</h3></div>${Number(v.is_default)?'<b class="k-account-vehicle-primary">Основной</b>':''}</div><p>${esc([vehicleBodyLabel(v.body_type||v.bodyType),v.plate||'Без госномера',Number(v.mileage_km||0).toLocaleString('ru-RU')+' км'].filter(Boolean).join(' · '))}</p><div class="k-account-vehicle-stats"><span><b>${Number(v.repair_count||0)}</b><small>ремонтов</small></span><span><b>${Number(v.document_count||0)}</b><small>документов</small></span><span><b>${Number(v.warranty_count||0)}</b><small>гарантий</small></span></div><div class="k-account-vehicle-actions"><a class="k-btn k-btn-primary" href="#/garage/car/${encodeURIComponent(v.id)}">Открыть автомобиль</a><a class="k-btn k-btn-secondary" href="#/orders/new?vehicleId=${encodeURIComponent(v.id)}">Создать заявку</a></div></div></article>`;}
  function renderCabinetVehicles(d){const items=Array.isArray(d.vehicles)?d.vehicles:[];if(!items.length)return `<section class="k-account-vehicles k-account-vehicles--empty" data-account-vehicles><header class="k-account-vehicles-head"><div><span>МОИ АВТОМОБИЛИ</span><h2>Гараж клиента</h2><p>Добавьте автомобиль — его ремонты, документы и сервисные сроки будут связаны с одним цифровым паспортом.</p></div></header><div class="k-client-account-empty"><b>В гараже пока нет автомобилей</b><p>Добавьте первый автомобиль, чтобы вести историю обслуживания и создавать заявки без повторного ввода данных.</p><a class="k-btn k-btn-primary" href="#/cabinet/garage">Добавить автомобиль</a></div></section>`;return `<section class="k-account-vehicles" data-account-vehicles><header class="k-account-vehicles-head"><div><span>МОИ АВТОМОБИЛИ</span><h2>Гараж клиента</h2><p>Реальные автомобили аккаунта. Никаких демонстрационных карточек и горизонтальных слайдеров.</p></div><a class="k-btn k-btn-secondary" href="#/cabinet/garage">Управление гаражом</a></header><div class="k-account-vehicles-grid">${items.map(cabinetVehicleCard).join('')}</div></section>`;}
  function mountCabinetVehicles(d){const host=document.querySelector('#k-client-vehicles-host');if(!host)return;host.innerHTML=renderCabinetVehicles(d);}
  async function mountCabinet(){const role=currentRole();if(role==='master'){try{const workplace=await window.KaretaApiClient?.request?.('api/db.php?action=masterWorkplace.get',{method:'GET',cacheTtlMs:0,force:true,dedupe:false});const payload=workplace?.payload?.data||workplace?.payload||{};const metrics=payload.metrics||{};const set=(id,value)=>{const node=document.getElementById(id);if(node)node.textContent=value;};set('k-master-cabinet-active',metrics.activeOrders??metrics.active??0);set('k-master-cabinet-done',metrics.completedOrders??metrics.completed??0);set('k-master-cabinet-rating',metrics.rating?Number(metrics.rating).toFixed(1):'—');set('k-master-cabinet-revenue',money(metrics.revenueMonth??metrics.revenue??0));}catch(_e){}return;}if(role!=='client')return;try{const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;const m=d.metrics||{};const set=(id,value)=>{const node=document.getElementById(id);if(node)node.textContent=String(value??0);};set('k-client-account-vehicles',m.vehicles||0);set('k-client-account-active',m.activeOrders||0);set('k-client-account-reminders',m.serviceReminders||0);set('k-client-account-completed',m.completedOrders||0);const host=document.querySelector('#k-client-profile-host');if(host){host.innerHTML=renderSocialProfile(d);}mountCabinetVehicles(d);}catch(e){if(e.message==='session_changed')return;const host=document.querySelector('#k-client-profile-host');if(host)host.innerHTML=`<div class="k-empty-card"><h2>Не удалось загрузить аккаунт</h2><p>${esc(e.message)}</p><button class="k-btn k-btn-primary" type="button" onclick="location.reload()">Повторить</button></div>`;const vehicles=document.querySelector('#k-client-vehicles-host');if(vehicles)vehicles.innerHTML='<div class="k-empty-card">Данные гаража временно недоступны.</div>';}}
  function vehicleTitle(v){return esc(v.title||[v.brand,v.model].filter(Boolean).join(' ')||'Автомобиль');}
  function garageCard(v){const title=vehicleTitle(v),logo=brandLogo(v.brand),fallback=esc((v.brand||'AUTO').slice(0,2).toUpperCase());return `<article class="k-garage-vehicle-card k-garage-car-r77 k-garage-card-r84" data-garage-vehicle-card="${esc(v.id)}"><div class="k-garage-vehicle-top k-garage-card-r84__head"><div class="k-garage-vehicle-mark">${logo?`<img class="k-garage-vehicle-brand-logo" src="${esc(logo)}" alt="${esc(v.brand||'Марка')}">`:fallback}</div><div class="k-garage-car-r77__title"><span>${v.is_default?'ОСНОВНОЙ АВТОМОБИЛЬ':esc(v.year_label||'АВТОМОБИЛЬ')}</span><h2>${title}</h2><p>${esc([v.year_label,v.plate].filter(Boolean).join(' · ')||'Госномер не указан')}</p></div>${v.is_default?'<b class="k-garage-primary-badge">Основной</b>':''}</div><div class="k-garage-vehicle-stats k-garage-card-r84__stats"><span><b>${Number(v.mileage_km||0).toLocaleString('ru-RU')}</b><small>км пробег</small></span><span><b>${Number(v.repair_count||0)}</b><small>ремонтов</small></span><span><b>${Number(v.document_count||0)}</b><small>документов</small></span></div><div class="k-garage-vehicle-actions k-garage-car-r77__actions k-garage-card-r84__actions"><a class="k-btn k-btn-primary" href="#/garage/car/${encodeURIComponent(v.id)}">Открыть автомобиль</a><button class="k-btn" type="button" data-garage-view="service" data-vehicle-id="${esc(v.id)}">Сервисная книжка</button></div><div class="k-garage-vehicle-manage k-garage-card-r84__manage">${v.is_default?'':`<button class="k-btn" type="button" data-garage-set-default="${esc(v.id)}">Сделать основным</button>`}<button class="k-btn" type="button" data-garage-edit-vehicle="${esc(v.id)}">Данные</button><button class="k-btn k-garage-danger" type="button" data-garage-archive-vehicle="${esc(v.id)}">В архив</button></div></article>`;}
  const garageIconMap=Object.freeze({cars:'car',service:'document',repairs:'services',carbook:'document',problems:'warning',operation:'oil',calendar:'calendar',systems:'grid',consumables:'airFilter'});
  const garageIcon=key=>window.KaretaUIIcons?.svg?.(garageIconMap[key]||'grid')||'';
  function garageCategory(key,title,text,count){return `<button class="k-garage-category k-garage-category--${key}" type="button" data-garage-view="${key}"><span class="k-garage-category-icon" aria-hidden="true">${garageIcon(key)}</span><span><b>${title}</b><small>${text}</small></span><em>${count}</em></button>`;}
  const garageWindowMeta={cars:['Мои машины','Управление автомобилями'],service:['Сервисные книжки','Регламент и техническое обслуживание'],repairs:['Книги ремонтов','Выполненные работы и расходы'],carbook:['Книги об автомобилях','Паспорт и характеристики'],problems:['Частые проблемы','Повторяющиеся обращения'],operation:['Эксплуатация','Расходники, гарантии и затраты'],calendar:['Календарь','Ближайшие сроки и напоминания'],systems:['Карта узлов','Системы и агрегаты автомобиля'],consumables:['Карта расходников','Детали, ресурс и сроки замены']};
  function garageWindow(type,content,hidden=false){const meta=garageWindowMeta[type]||[type,''];return `<section class="k-garage-view k-garage-window k-garage-window--${type}" id="k-garage-panel-${type}" data-garage-panel="${type}" role="dialog" aria-modal="true" aria-labelledby="k-garage-panel-title-${type}" ${hidden?'hidden':''}><header class="k-garage-window-bar"><span class="k-garage-window-icon" aria-hidden="true">${garageIcon(type)}</span><div><b id="k-garage-panel-title-${type}">${meta[0]}</b><small>${meta[1]}</small></div><button class="k-garage-window-close" type="button" data-garage-modal-close aria-label="Закрыть окно">${window.KaretaUIIcons?.icon?.('close')||''}</button></header><div class="k-garage-window-body">${content}</div></section>`;}
  function vehicleOrders(d,vehicleId){return (d.orders||[]).filter(o=>String(o.client_vehicle_id||o.vehicle_id||'')===String(vehicleId));}
  function bookHeader(v,type,title,text){return `<div class="k-garage-book-head"><div><span>${esc(type)}</span><h2>${vehicleTitle(v)}</h2><p>${esc(title)}</p><small>${esc(text)}</small></div><a class="k-btn" href="#/garage/car/${encodeURIComponent(v.id)}">Полная карточка</a></div>`;}
  function emptyBook(text){return `<div class="k-garage-book-empty">${esc(text)}</div>`;}
  function serviceBook(v,d){const orders=vehicleOrders(d,v.id);const rows=orders.map(o=>`<a class="k-garage-book-row" href="#/orders/item/${encodeURIComponent(o.id)}"><span><b>${esc(o.service_names||'Сервисная работа')}</b><small>${esc(o.created_at||o.date||'Дата не указана')}</small></span><strong>${money(o.price||0)}</strong></a>`).join('');return `<article class="k-garage-book">${bookHeader(v,'СЕРВИСНАЯ КНИЖКА','Обслуживание и регламентные работы','Записи формируются из подтверждённых заявок и заказ-нарядов.')}${rows||emptyBook('Записей обслуживания пока нет. После первого заказа они появятся автоматически.')}</article>`;}
  function repairBook(v,d){const orders=vehicleOrders(d,v.id);const rows=orders.map(o=>`<a class="k-garage-repair-record" href="#/orders/item/${encodeURIComponent(o.id)}"><div><span>${esc(o.status||'Заказ')}</span><h3>${esc(o.service_names||'Ремонт')}</h3><p>${esc(o.created_at||o.date||'')} · ${esc(o.master_name||o.sto_name||'Исполнитель не указан')}</p></div><strong>${money(o.price||0)}</strong></a>`).join('');return `<article class="k-garage-book">${bookHeader(v,'КНИГА РЕМОНТОВ','Полная история выполненных работ','Каждая запись связана с заказ-нарядом, стоимостью и исполнителем.')}${rows||emptyBook('Ремонтов пока нет.')}</article>`;}
  function carBook(v){const specs=[['Марка',v.brand],['Модель',v.model],['Год',v.year_label||v.year],['Поколение',v.generation],['Кузов',vehicleBodyLabel(v.body_type||v.bodyType)],['Госномер',v.plate],['VIN',v.vin],['Пробег',Number(v.mileage_km||0)?Number(v.mileage_km||0).toLocaleString('ru-RU')+' км':''],['Двигатель',v.engine_volume],['Топливо',v.fuel_type||v.engine_type]];return `<article class="k-garage-book">${bookHeader(v,'КНИГА ОБ АВТОМОБИЛЕ','Паспорт и основные сведения','Минимальная карточка создаётся при первом входе. Подробные характеристики владелец дополняет здесь, в гараже.') }<div class="k-garage-spec-grid">${specs.map(([k,val])=>`<div><small>${k}</small><b>${esc(val||'Не указано')}</b></div>`).join('')}</div><button class="k-btn k-btn-primary" type="button" data-garage-edit-vehicle="${esc(v.id)}">Изменить данные автомобиля</button></article>`;}
  function problemBook(v,d){const orders=vehicleOrders(d,v.id);const names=orders.map(o=>String(o.service_names||'').trim()).filter(Boolean);const freq={};names.forEach(n=>freq[n]=(freq[n]||0)+1);const sorted=Object.entries(freq).sort((a,b)=>b[1]-a[1]);const rows=sorted.map(([name,count])=>`<div class="k-garage-problem-row"><span><b>${esc(name)}</b><small>Зафиксировано в истории ремонта</small></span><em>${count}</em></div>`).join('');return `<article class="k-garage-book">${bookHeader(v,'КНИГА ЧАСТЫХ ПРОБЛЕМ','Наблюдения по истории именно этой машины','Раздел не ставит диагноз. Он показывает повторяющиеся обращения и помогает не потерять закономерности.')}${rows||emptyBook('Повторяющихся обращений пока не зафиксировано.')}</article>`;}
  function operationBook(v,d){const vid=String(v.id||'');const maintenance=(d.maintenance||[]).filter(x=>String(x.vehicle_id)===vid);const expenses=(d.expenses||[]).filter(x=>String(x.vehicle_id)===vid);const warranties=(d.warranties||[]).filter(x=>String(x.vehicle_id)===vid);const itemNames={oil:'Масло',filter:'Фильтр',spark_plugs:'Свечи',belt:'Ремень',coolant:'Охлаждающая жидкость',brake_fluid:'Тормозная жидкость',tires:'Шины',battery:'Аккумулятор',other:'Другое'};const rows=maintenance.map(x=>`<div class="k-maintenance-row"><span><b>${esc(x.title)}</b><small>${esc(itemNames[x.item_type]||'Обслуживание')} · следующее: ${esc(x.next_due_at||'по пробегу')} ${x.next_due_mileage_km?`/ ${Number(x.next_due_mileage_km).toLocaleString('ru-RU')} км`:''}</small></span><em>${esc(x.brand||x.model||'')}</em></div>`).join('')||emptyBook('Расходники и обслуживание ещё не добавлены.');const warrantyRows=warranties.map(x=>`<div class="k-maintenance-row"><span><b>${esc(x.title)}</b><small>${esc(x.provider_name||'Гарантия')} · до ${esc(x.expires_at||'без срока')}</small></span><em>${x.mileage_limit_km?Number(x.mileage_limit_km).toLocaleString('ru-RU')+' км':''}</em></div>`).join('')||emptyBook('Активных гарантий пока нет.');const total=expenses.reduce((sum,x)=>sum+Number(x.amount||0),0);const expenseRows=expenses.slice(0,8).map(x=>`<div class="k-maintenance-row"><span><b>${esc(x.title)}</b><small>${esc(x.expense_date||'')} · ${esc(x.expense_type||'расход')}</small></span><strong>${money(x.amount)}</strong></div>`).join('')||emptyBook('Дополнительные расходы пока не добавлены.');return `<article class="k-garage-book">${bookHeader(v,'ЭКСПЛУАТАЦИЯ','ТО, расходники, гарантии и расходы',`Учёт эксплуатации конкретного автомобиля. Всего дополнительных расходов: ${money(total)}.`)}<div class="k-operation-sections"><section><h3>Расходники и ТО</h3>${rows}${maintenanceForm(v)}</section><section><h3>Гарантии</h3>${warrantyRows}${warrantyForm(v)}</section><section><h3>Расходы</h3>${expenseRows}${expenseForm(v)}</section></div></article>`;}
  function maintenanceForm(v){const types=[['oil','Масло'],['filter','Фильтр'],['spark_plugs','Свечи'],['belt','Ремень'],['coolant','Охлаждающая жидкость'],['tires','Шины'],['battery','Аккумулятор'],['other','Другое']];return `<details class="k-garage-add"><summary>Добавить обслуживание</summary><form data-maintenance-form><input type="hidden" name="vehicleId" value="${esc(v.id)}"><fieldset class="k-garage-choice-field"><legend>Тип</legend><div>${types.map(([value,label],index)=>`<label><input type="radio" name="itemType" value="${value}" ${index===0?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><label>Название<input name="title" required placeholder="Например, моторное масло"></label><label>Бренд<input name="brand"></label><label>Следующая дата<input name="nextDueAt" type="date"></label><label>Следующий пробег<input name="nextDueMileageKm" type="number" min="0"></label><button class="k-btn k-btn-primary" type="submit">Сохранить</button></form></details>`;}
  function warrantyForm(v){return `<details class="k-garage-add"><summary>Добавить гарантию</summary><form data-warranty-form><input type="hidden" name="vehicleId" value="${esc(v.id)}"><label>Что покрывает<input name="title" required></label><label>Кто выдал<input name="providerName"></label><label>Действует до<input name="expiresAt" type="date"></label><label>Лимит пробега<input name="mileageLimitKm" type="number" min="0"></label><button class="k-btn k-btn-primary" type="submit">Сохранить</button></form></details>`;}
  function expenseForm(v){return `<details class="k-garage-add"><summary>Добавить расход</summary><form data-expense-form><input type="hidden" name="vehicleId" value="${esc(v.id)}"><label>Расход<input name="title" required></label><label>Сумма<input name="amount" type="number" min="1" required></label><label>Дата<input name="expenseDate" type="date"></label><button class="k-btn k-btn-primary" type="submit">Сохранить</button></form></details>`;}

  function reminderText(r){const parts=[];if(r.due_at)parts.push(`до ${esc(r.due_at)}`);if(r.km_left!==null&&r.km_left!==undefined){const km=Number(r.km_left||0);parts.push(km<0?`перепробег ${Math.abs(km).toLocaleString('ru-RU')} км`:`осталось ${km.toLocaleString('ru-RU')} км`);}return parts.join(' · ')||'Без точного срока';}
  function serviceCalendarBook(v,d){const vid=String(v.id||'');const rows=(d.reminders||[]).filter(r=>String(r.vehicle_id)===vid).map(r=>`<article class="k-service-reminder k-service-reminder--${esc(r.level||'planned')}"><div><span>${r.type==='warranty'?'ГАРАНТИЯ':(r.type==='document'?'ДОКУМЕНТ':'ОБСЛУЖИВАНИЕ')}</span><h3>${esc(r.title||'Сервисная задача')}</h3><p>${reminderText(r)}</p></div><b>${r.level==='overdue'?'Просрочено':(r.level==='soon'?'Скоро':'Запланировано')}</b></article>`).join('');return `<article class="k-garage-book">${bookHeader(v,'СЕРВИСНЫЙ КАЛЕНДАРЬ','Ближайшие задачи и сроки','Календарь собирается из ТО, пробега, расходников и гарантий автомобиля.')}<div class="k-service-calendar-list">${rows||emptyBook('Ближайших сервисных задач пока нет.')}</div><a class="k-btn k-btn-primary" href="#/orders/new">Записаться на обслуживание</a></article>`;}

  function garageBooks(d,type){const vehicles=d.vehicles||[];if(!vehicles.length)return '<div class="k-empty-card"><h2>Сначала добавьте автомобиль</h2><p>После этого для него появятся сервисная книжка, история ремонтов и технические записи.</p></div>';const renderer={service:serviceBook,repairs:repairBook,carbook:(v)=>carBook(v),problems:problemBook,operation:operationBook,calendar:serviceCalendarBook}[type]||serviceBook;return `<div class="k-garage-books">${vehicles.map(v=>renderer(v,d)).join('')}</div>`;}

  const serviceSystems=[
    {id:'engine',title:'Двигатель',text:'Смазка, зажигание, впуск и навесное оборудование'},
    {id:'timing',title:'ГРМ и приводы',text:'Ремень или цепь, ролики, натяжители и помпа'},
    {id:'cooling',title:'Система охлаждения',text:'Антифриз, термостат, радиатор, патрубки и помпа'},
    {id:'transmission',title:'Трансмиссия',text:'Масло КПП, сцепление, ШРУСы и приводы'},
    {id:'suspension',title:'Подвеска и ступицы',text:'Подшипники, амортизаторы, опоры и сайлентблоки'},
    {id:'brakes',title:'Тормозная система',text:'Колодки, диски, жидкость, шланги и суппорты'},
    {id:'steering',title:'Рулевое управление',text:'Наконечники, тяги, рейка и рабочая жидкость'},
    {id:'electrics',title:'Электрика',text:'АКБ, генератор, стартер, лампы и проводка'},
    {id:'climate',title:'Климатическая система',text:'Фильтр салона, хладагент, компрессор и радиаторы'},
    {id:'fuel',title:'Топливная система',text:'Фильтр, насос, форсунки и магистрали'}
  ];
  const serviceConsumables=[
    {id:'engine_oil',system:'engine',title:'Моторное масло',km:10000,months:12,mode:'interval'},
    {id:'oil_filter',system:'engine',title:'Масляный фильтр',km:10000,months:12,mode:'interval'},
    {id:'air_filter',system:'engine',title:'Воздушный фильтр',km:15000,months:12,mode:'interval'},
    {id:'spark_plugs',system:'engine',title:'Свечи зажигания',km:30000,months:24,mode:'interval'},
    {id:'timing_belt',system:'timing',title:'Ремень ГРМ',km:60000,months:48,mode:'interval'},
    {id:'timing_rollers',system:'timing',title:'Ролики ГРМ',km:60000,months:48,mode:'interval'},
    {id:'water_pump',system:'timing',title:'Помпа',km:60000,months:48,mode:'interval'},
    {id:'drive_belt',system:'timing',title:'Приводной ремень',km:50000,months:36,mode:'interval'},
    {id:'coolant',system:'cooling',title:'Охлаждающая жидкость',km:60000,months:36,mode:'interval'},
    {id:'thermostat',system:'cooling',title:'Термостат',km:0,months:0,mode:'condition'},
    {id:'gear_oil',system:'transmission',title:'Масло КПП / АКПП',km:60000,months:48,mode:'interval'},
    {id:'clutch',system:'transmission',title:'Комплект сцепления',km:0,months:0,mode:'condition'},
    {id:'wheel_bearing',system:'suspension',title:'Ступичные подшипники',km:0,months:0,mode:'condition'},
    {id:'shock_absorber',system:'suspension',title:'Амортизаторы',km:0,months:0,mode:'condition'},
    {id:'brake_pads',system:'brakes',title:'Тормозные колодки',km:0,months:0,mode:'condition'},
    {id:'brake_fluid',system:'brakes',title:'Тормозная жидкость',km:40000,months:24,mode:'interval'},
    {id:'tie_rod',system:'steering',title:'Рулевые наконечники и тяги',km:0,months:0,mode:'condition'},
    {id:'battery',system:'electrics',title:'Аккумулятор',km:0,months:48,mode:'condition'},
    {id:'cabin_filter',system:'climate',title:'Салонный фильтр',km:15000,months:12,mode:'interval'},
    {id:'fuel_filter',system:'fuel',title:'Топливный фильтр',km:30000,months:24,mode:'interval'}
  ];
  function selectedVehicle(d){const vehicles=d.vehicles||[];return vehicles.find(v=>String(v.id)===String(serviceVehicleId))||vehicles.find(v=>Number(v.is_default)===1)||vehicles[0]||null;}
  function vehicleSwitcher(d,v){const vehicles=d.vehicles||[];return `<div class="k-service-vehicle-switcher-r78"><span>Автомобиль</span><div>${vehicles.map(x=>`<button type="button" data-service-vehicle-pick="${esc(x.id)}" class="${String(x.id)===String(v.id)?'is-selected':''}"><b>${vehicleTitle(x)}</b><small>${Number(x.mileage_km||0).toLocaleString('ru-RU')} км</small></button>`).join('')}</div></div>`;}
  function maintenanceMatch(d,v,item){const vid=String(v?.id||'');const direct=(d.maintenance||[]).filter(x=>String(x.vehicle_id)===vid).find(x=>String(x.item_type||'')===item.id);if(direct)return direct;const words=item.title.toLowerCase().split(/\s+/).filter(x=>x.length>3);return (d.maintenance||[]).filter(x=>String(x.vehicle_id)===vid).find(x=>words.some(w=>String(x.title||'').toLowerCase().includes(w)));}
  function resourceState(d,v,item){const rec=maintenanceMatch(d,v,item);if(item.mode==='condition')return {key:rec?'watch':'check',label:rec?'Под наблюдением':'Нужна проверка',used:null,left:null,rec};const current=Number(v?.mileage_km||0),last=Number(rec?.installed_mileage_km||rec?.mileage_km||rec?.last_mileage_km||0),used=last>0?Math.max(0,current-last):null,left=used===null?null:item.km-used;if(used===null)return {key:'unknown',label:'Нет истории',used,left,rec};if(left<=0)return {key:'overdue',label:'Срок вышел',used,left:0,rec};if(left<=Math.max(1000,item.km*.15))return {key:'soon',label:'Скоро замена',used,left,rec};return {key:'ok',label:'В норме',used,left,rec};}
  function serviceHealth(d,v){const states=serviceConsumables.map(item=>resourceState(d,v,item));const count=key=>states.filter(x=>x.key===key).length;return `<div class="k-service-health"><span class="is-ok"><b>${count('ok')}</b><small>в норме</small></span><span class="is-soon"><b>${count('soon')}</b><small>скоро</small></span><span class="is-overdue"><b>${count('overdue')}</b><small>просрочено</small></span><span class="is-check"><b>${count('check')+count('watch')}</b><small>проверить</small></span><span class="is-unknown"><b>${count('unknown')}</b><small>нет истории</small></span></div>`;}
  function systemsMap(d){const v=selectedVehicle(d);if(!v)return emptyBook('Сначала добавьте автомобиль. После этого появятся две связанные сервисные карты.');return `${vehicleSwitcher(d,v)}<div class="k-service-map-intro"><div><span>КАРТА №1</span><h2>${vehicleTitle(v)}</h2><p>Системы и агрегаты автомобиля. Каждая категория связана со своими деталями в карте расходников.</p></div><b>${Number(v.mileage_km||0).toLocaleString('ru-RU')} км</b></div>${serviceHealth(d,v)}<div class="k-service-system-grid">${serviceSystems.map(sys=>{const items=serviceConsumables.filter(x=>x.system===sys.id),alerts=items.filter(x=>['overdue','soon','check','watch'].includes(resourceState(d,v,x).key)).length;return `<button type="button" class="k-service-system-card ${alerts?'has-alerts':''}" data-service-system-open="${sys.id}"><span>${garageIcon('systems')}</span><div><b>${sys.title}</b><small>${sys.text}</small><em>${items.length} элементов${alerts?` · ${alerts} требуют внимания`:''}</em></div><i>›</i></button>`;}).join('')}</div>`;}
  function serviceRecordForm(v,item,st){const nextMileage=item.mode==='interval'?Number(v.mileage_km||0)+Number(item.km||0):'';return `<details class="k-service-record"><summary>Отметить замену / проверку</summary><form data-service-maintenance-form><input type="hidden" name="vehicleId" value="${esc(v.id)}"><input type="hidden" name="itemType" value="${esc(item.id)}"><input type="hidden" name="title" value="${esc(item.title)}"><label>Дата<input name="installedAt" type="date" required></label><label>Пробег при работе<input name="installedMileageKm" type="number" min="0" value="${Number(v.mileage_km||0)}" required></label>${item.mode==='interval'?`<label>Следующая замена, км<input name="nextDueMileageKm" type="number" min="0" value="${nextMileage}"></label>`:''}<label>Бренд / производитель<input name="brand" value="${esc(st.rec?.brand||'')}"></label><label class="k-service-record-wide">Комментарий<input name="note" placeholder="Что заменено или проверено"></label><button class="k-btn k-btn-primary" type="submit">Сохранить запись</button></form></details>`;}
  function consumablesMap(d){const v=selectedVehicle(d);if(!v)return emptyBook('Сначала добавьте автомобиль.');return `${vehicleSwitcher(d,v)}<div class="k-service-map-intro"><div><span>КАРТА №2</span><h2>Детали и расходники</h2><p>Отмечайте фактическую замену или проверку. Карта пересчитает остаток ресурса по текущему пробегу автомобиля.</p></div><button class="k-btn" type="button" data-service-filter-reset>Все категории</button></div><div class="k-service-toolbar k-service-toolbar-r78"><input type="search" data-service-search placeholder="Найти ремень, фильтр, подшипник…"><div class="k-service-status-buttons" data-service-status-buttons><button type="button" class="is-selected" data-service-status-filter="">Все</button><button type="button" data-service-status-filter="overdue">Срок вышел</button><button type="button" data-service-status-filter="soon">Скоро</button><button type="button" data-service-status-filter="check">Проверить</button><button type="button" data-service-status-filter="unknown">Нет истории</button><button type="button" data-service-status-filter="ok">В норме</button></div></div>${serviceHealth(d,v)}<div class="k-service-consumable-list">${serviceSystems.map(sys=>`<section class="k-service-consumable-group" data-service-system-group="${sys.id}"><header><div><span>${garageIcon('consumables')}</span><b>${sys.title}</b></div><small>${serviceConsumables.filter(x=>x.system===sys.id).length} элементов</small></header>${serviceConsumables.filter(x=>x.system===sys.id).map(item=>{const st=resourceState(d,v,item);const interval=item.mode==='condition'?'Замена по состоянию':`${item.km.toLocaleString('ru-RU')} км${item.months?` или ${item.months} мес.`:''}`;return `<article class="k-service-resource-card k-service-resource-card--${st.key}" data-service-resource data-resource-state="${st.key}" data-resource-search="${esc((item.title+' '+sys.title).toLowerCase())}"><div><span>${item.mode==='condition'?'ПО СОСТОЯНИЮ':'РЕГЛАМЕНТ'}</span><h3>${item.title}</h3><p>${interval}</p>${st.used!==null?`<small>После последней отметки: ${st.used.toLocaleString('ru-RU')} км${st.left!==null?` · осталось ${st.left.toLocaleString('ru-RU')} км`:''}</small>`:'<small>Последняя замена не указана</small>'}${st.rec?`<small>Последняя запись: ${esc(st.rec.installed_at||'дата не указана')} · ${Number(st.rec.installed_mileage_km||0).toLocaleString('ru-RU')} км</small>`:''}</div><b>${st.label}</b><a class="k-btn" href="#/orders/new">Запланировать</a>${serviceRecordForm(v,item,st)}</article>`;}).join('')}</section>`).join('')}</div>`;}

  function archivedGarageCard(v){return `<article class="k-garage-archived-card"><div><span>В АРХИВЕ</span><h3>${vehicleTitle(v)}</h3><p>${esc([v.year_label,v.plate].filter(Boolean).join(' · ')||'Данные автомобиля сохранены')}</p></div><button class="k-btn" type="button" data-garage-restore-vehicle="${esc(v.id)}">Восстановить</button></article>`;}
  function garageLayout(d){const vehicles=d.vehicles||[],archived=d.archivedVehicles||[],orders=d.orders||[];if(!vehicles.length&&!archived.length)return `<section class="k-garage-empty-r77">${firstVehicleFlow.emptyGarage()}</section>`;const actions=`<div class="k-garage-categories k-garage-actions-r78 k-garage-tools-grid-r77" aria-label="Разделы гаража">${garageCategory('systems','Карта узлов','Системы автомобиля',serviceSystems.length)}${garageCategory('consumables','Расходники','Ресурс и замены',serviceConsumables.length)}${garageCategory('service','Сервис','ТО и обслуживание',orders.length)}${garageCategory('repairs','Ремонты','Выполненные работы',orders.length)}${garageCategory('carbook','Паспорт','Характеристики',vehicles.length)}${garageCategory('problems','Проблемы','Повторные обращения',vehicles.length)}${garageCategory('operation','Эксплуатация','Гарантии и расходы',(d.maintenance||[]).length)}${garageCategory('calendar','Календарь','Сроки и напоминания',(d.reminders||[]).filter(r=>r.level==='overdue'||r.level==='soon').length)}</div>`;const cars=`<section class="k-garage-workspace-r78 k-garage-workspace-r77"><header><div><span>ВАШИ АВТОМОБИЛИ</span><h2>${vehicles.length?`${vehicles.length} ${vehicles.length===1?'автомобиль':'автомобиля'}`:'Нет активных автомобилей'}</h2><p>Основной автомобиль автоматически используется при создании новой заявки.</p></div></header><div class="k-garage-grid k-garage-grid-r78 k-garage-grid-r77">${vehicles.map(garageCard).join('')||'<div class="k-empty-card"><h2>Нет активных автомобилей</h2><p>Добавьте автомобиль или восстановите его из архива.</p></div>'}</div></section>`;const archive=archived.length?`<details class="k-garage-archive k-garage-archive-r77"><summary><span>АРХИВ</span><b>${archived.length} ${archived.length===1?'автомобиль':'автомобиля'}</b><small>История и документы сохранены</small></summary><div>${archived.map(archivedGarageCard).join('')}</div></details>`:'';return `${cars}<section class="k-garage-tools-r78 k-garage-tools-r77"><header><div><span>СЕРВИС АВТОМОБИЛЯ</span><h2>История и контроль состояния</h2><p>Открывайте только нужный раздел — без длинной страницы из вложенных карточек.</p></div><a class="k-garage-request-r77" href="#/orders/new">Создать заявку</a></header>${actions}</section>${archive}<dialog class="k-garage-dialog-r78 k-garage-dialog-r77" data-garage-dialog><div class="k-garage-dialog-surface"><header><div><small data-garage-dialog-eyebrow>МОЙ ГАРАЖ</small><h2 data-garage-dialog-title>Раздел гаража</h2></div><button type="button" data-garage-dialog-close aria-label="Закрыть">${window.KaretaUIIcons?.icon?.('close')||''}</button></header><div class="k-garage-dialog-body" data-garage-dialog-body></div></div></dialog>`;}
  function bindGarageTabs(){const root=document.querySelector('#k-page-outlet .k-client-cabinet-page');if(!root)return;const dialog=root.querySelector('[data-garage-dialog]'),body=dialog?.querySelector('[data-garage-dialog-body]'),title=dialog?.querySelector('[data-garage-dialog-title]'),eyebrow=dialog?.querySelector('[data-garage-dialog-eyebrow]');let activeType='';const close=()=>{if(dialog?.open){try{dialog.close();}catch(_e){}}activeType='';};const refresh=async(message='')=>{window.KaretaApiClient?.invalidate?.('client.cabinet');data=null;if(message)window.KaretaToast?.success?.(message);await mountGarage();};const contentFor=key=>{if(key==='systems')return systemsMap(data||{});if(key==='consumables')return consumablesMap(data||{});if(['service','repairs','carbook','problems','operation','calendar'].includes(key))return garageBooks(data||{},key);return'';};const open=(key,label='')=>{if(!dialog||!body)return;activeType=key;const meta=garageWindowMeta[key]||[label||'Раздел гаража','МОЙ ГАРАЖ'];title.textContent=meta[0];eyebrow.textContent='РАБОЧЕЕ ОКНО';body.innerHTML=contentFor(key);if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>dialog.querySelector('button,input,[tabindex]')?.focus?.({preventScroll:true}));};const applyResourceFilter=()=>{const term=String(dialog?.querySelector('[data-service-search]')?.value||'').trim().toLowerCase();const state=dialog?.querySelector('[data-service-status-filter].is-selected')?.dataset.serviceStatusFilter||'';dialog?.querySelectorAll('[data-service-resource]').forEach(card=>{card.hidden=Boolean((term&&!card.dataset.resourceSearch.includes(term))||(state&&card.dataset.resourceState!==state));});dialog?.querySelectorAll('[data-service-system-group]').forEach(group=>{group.hidden=![...group.querySelectorAll('[data-service-resource]')].some(card=>!card.hidden);});};root.addEventListener('click',async e=>{if(e.target===dialog||e.target.closest('[data-garage-dialog-close]')){close();return;}if(e.target.closest('[data-garage-add-vehicle]')){close();firstVehicleFlow.start({root,startStep:2,data:data||{},mode:'manual',onReturn:()=>{data=null;mountGarage();}});return;}const setPrimary=e.target.closest('[data-garage-set-default]');if(setPrimary){const r=await api.setDefaultVehicle(setPrimary.dataset.garageSetDefault);if(!r?.ok){window.KaretaToast?.error?.(r?.payload?.message||'Не удалось выбрать основной автомобиль');return;}await refresh('Основной автомобиль изменён');return;}const edit=e.target.closest('[data-garage-edit-vehicle]');if(edit){const vehicle=(data?.vehicles||[]).find(v=>String(v.id)===String(edit.dataset.garageEditVehicle));if(vehicle){close();firstVehicleFlow.start({root,startStep:2,data:data||{},mode:'edit',vehicle,onReturn:()=>{data=null;mountGarage();}});}return;}const archive=e.target.closest('[data-garage-archive-vehicle]');if(archive){const vehicle=(data?.vehicles||[]).find(v=>String(v.id)===String(archive.dataset.garageArchiveVehicle));const ok=window.KaretaNativeDialogs?.confirm?await window.KaretaNativeDialogs.confirm({title:'Переместить автомобиль в архив?',message:`${vehicleTitle(vehicle||{})} исчезнет из активного гаража. История ремонтов и документы сохранятся.`,confirmLabel:'В архив',danger:true,trigger:archive}):window.confirm(`Переместить ${vehicleTitle(vehicle||{})} в архив? История ремонтов и документы сохранятся.`);if(!ok)return;const r=await api.archiveVehicle(archive.dataset.garageArchiveVehicle);if(!r?.ok){window.KaretaToast?.error?.(r?.payload?.message||'Не удалось архивировать автомобиль');return;}await refresh(r.payload?.newDefaultId?'Автомобиль архивирован. Новый основной выбран автоматически.':'Автомобиль перемещён в архив');return;}const restore=e.target.closest('[data-garage-restore-vehicle]');if(restore){const r=await api.restoreVehicle(restore.dataset.garageRestoreVehicle);if(!r?.ok){window.KaretaToast?.error?.(r?.payload?.message||'Не удалось восстановить автомобиль');return;}await refresh('Автомобиль восстановлен');return;}const systemButton=e.target.closest('[data-service-system-open]');if(systemButton){body.innerHTML=consumablesMap(data||{});activeType='consumables';title.textContent='Карта расходников';const id=systemButton.dataset.serviceSystemOpen;dialog.querySelectorAll('[data-service-system-group]').forEach(group=>group.hidden=group.dataset.serviceSystemGroup!==id);return;}const reset=e.target.closest('[data-service-filter-reset]');if(reset){dialog.querySelectorAll('[data-service-system-group]').forEach(group=>group.hidden=false);const search=dialog.querySelector('[data-service-search]');if(search)search.value='';dialog.querySelectorAll('[data-service-status-filter]').forEach(b=>b.classList.toggle('is-selected',!b.dataset.serviceStatusFilter));dialog.querySelectorAll('[data-service-resource]').forEach(card=>card.hidden=false);return;}const status=e.target.closest('[data-service-status-filter]');if(status){dialog.querySelectorAll('[data-service-status-filter]').forEach(b=>b.classList.toggle('is-selected',b===status));applyResourceFilter();return;}const vehicle=e.target.closest('[data-service-vehicle-pick]');if(vehicle){serviceVehicleId=vehicle.dataset.serviceVehiclePick;body.innerHTML=activeType==='consumables'?consumablesMap(data||{}):systemsMap(data||{});return;}const b=e.target.closest('[data-garage-view]');if(b){e.preventDefault();open(b.dataset.garageView);return;}});root.addEventListener('input',e=>{if(e.target.matches('[data-service-search]'))applyResourceFilter();});dialog?.addEventListener('cancel',e=>{e.preventDefault();close();});return {open,close};}

  async function mountGarage(){
    if(!isClientCabinetRole())return;
    try{
      const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;
      const directFirstVehicle=/(?:\?|&)firstVehicle=1(?:&|$)/.test(String(location.hash||''));
      const wantsIntro=Boolean(firstVehicleFlow?.consumePendingIntro?.());
      if((directFirstVehicle||wantsIntro)&&!(d.vehicles||[]).length){
        replace(garageShell(d,`<div data-first-vehicle-bootstrap></div>`));
        const flowRoot=document.querySelector('#k-page-outlet .k-client-cabinet-page');
        if(directFirstVehicle){try{history.replaceState(null,'','#/cabinet/garage');}catch(_e){}}firstVehicleFlow.start({root:flowRoot,startStep:directFirstVehicle?2:1,data:d,mode:directFirstVehicle?'manual':'intro',onReturn:()=>{data=null;mountGarage();}});
        return;
      }
      replace(garageShell(d,garageLayout(d)));
      bindGarageTabs();
      const root=document.querySelector('#k-page-outlet .k-client-cabinet-page');
      root?.addEventListener('submit',async ev=>{
        const form=ev.target;
        if(!(form instanceof HTMLFormElement))return;
        let save=null;
        if(form.matches('[data-maintenance-form],[data-service-maintenance-form]'))save=api.saveMaintenance;
        if(form.matches('[data-expense-form]'))save=api.saveExpense;
        if(form.matches('[data-warranty-form]'))save=api.saveWarranty;
        if(!save)return;
        ev.preventDefault();
        const payload=Object.fromEntries(new FormData(form).entries());
        const r=await save(payload);
        if(!r.ok){window.KaretaToast?.error(r.payload?.message||'Не удалось сохранить');return;}
        window.KaretaApiClient.invalidate('client.cabinet');data=null;window.KaretaToast?.success('Запись сохранена');
        const serviceRecord=form.matches('[data-service-maintenance-form]');
        await mountGarage();document.querySelector(`[data-garage-view="${serviceRecord?'consumables':'operation'}"]`)?.click();
      });
    }catch(e){if(e.message==='session_changed')return;replace(shell('Мой гараж','',`<div class="k-empty-card">${esc(e.message)}</div>`));}
  }

  async function mountData(){if(!isClientCabinetRole())return;const role=currentRole();if(role==='client'||role==='admin'||role==='owner'){openClientAccountWindow('profile');return;}try{const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;const u=d.user||{};replace(shell('Мои данные','Контактные данные владельца аккаунта.',`<div class="k-empty-card"><h2>${esc(u.name||'Профиль')}</h2><p>${esc(u.phone||'')}</p><p>${esc(u.city||'')}</p></div>`));}catch(e){if(e.message==='session_changed')return;replace(shell('Мои данные','',`<div class="k-empty-card">${esc(e.message)}</div>`));}}
  async function mountHistory(){if(!isClientCabinetRole())return;try{const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;const rows=(d.orders||[]).map(o=>`<a class="k-history-row" href="#/orders/item/${encodeURIComponent(o.id)}"><span><b>${esc(o.service_names||'Заявка')}</b><small>${esc(o.vehicle_title||o.client_car||'Автомобиль')} · ${esc(o.created_at||'')}</small></span><strong>${money(o.price)}</strong><i>${esc(o.status||'')}</i></a>`).join('')||'<div class="k-empty-card">История пока пуста.</div>';replace(shell('История',`Всего расходов: ${money(d.metrics?.spent||0)}.`,`<div class="k-history-list">${rows}</div>`));}catch(e){if(e.message==='session_changed')return;replace(shell('История','',`<div class="k-empty-card">${esc(e.message)}</div>`));}}
  const documentTypeLabel={insurance:'Страховка',inspection:'Техосмотр',registration:'Регистрация',power_of_attorney:'Доверенность',service:'Сервисный документ',warranty:'Гарантия',other:'Документ'};
  function documentState(doc){if(!doc.expires_at)return {key:'active',label:'Без срока'};const days=Math.ceil((new Date(doc.expires_at+'T00:00:00')-new Date())/86400000);if(days<0)return {key:'expired',label:'Просрочен'};if(days<=Number(doc.reminder_days||30))return {key:'soon',label:`Осталось ${days} дн.`};return {key:'active',label:`До ${esc(doc.expires_at)}`};}
  function documentChoice(name,value,label,current){return `<button type="button" class="k-r84-choice ${String(value)===String(current)?'is-active':''}" data-cabinet-doc-choice="${esc(name)}" data-value="${esc(value)}">${esc(label)}</button>`;}
  function documentForm(d){const vehicles=d.vehicles||[];if(!vehicles.length)return '<div class="k-empty-card"><h2>Сначала добавьте автомобиль</h2><p>Документы всегда привязываются к конкретной машине.</p><a class="k-btn k-btn-primary" href="#/cabinet/garage">Добавить автомобиль</a></div>';const vehicle=String(vehicles[0]?.id||'');const type='insurance',reminder='30';return `<form id="k-client-document-form" class="k-document-form"><div class="k-document-form-head"><span>НОВЫЙ ДОКУМЕНТ</span><h2>Добавить в цифровой архив</h2><p>Страховка, техосмотр, регистрационные и сервисные документы хранятся по конкретному автомобилю.</p></div><div class="k-document-form-grid"><section class="k-r84-choice-block k-document-form-wide"><span>Автомобиль</span><input type="hidden" name="vehicleId" value="${esc(vehicle)}"> <div class="k-r84-choice-grid">${vehicles.map(v=>documentChoice('vehicleId',v.id,vehicleTitle(v),vehicle)).join('')}</div></section><section class="k-r84-choice-block k-document-form-wide"><span>Тип</span><input type="hidden" name="documentType" value="${type}"><div class="k-r84-choice-grid">${Object.entries(documentTypeLabel).map(([v,l])=>documentChoice('documentType',v,l,type)).join('')}</div></section><label>Название<input name="title" required placeholder="Полис ОГПО"></label><label>Номер<input name="documentNumber" placeholder="Номер документа"></label><label>Кем выдан<input name="issuerName" placeholder="Страховая компания или орган"></label><label>Дата выдачи<input name="issuedAt" type="date"></label><label>Действует до<input name="expiresAt" type="date"></label><section class="k-r84-choice-block k-document-form-wide"><span>Напомнить заранее</span><input type="hidden" name="reminderDays" value="${reminder}"><div class="k-r84-choice-grid">${[[7,'За 7 дней'],[14,'За 14 дней'],[30,'За 30 дней'],[60,'За 60 дней'],[90,'За 90 дней']].map(([v,l])=>documentChoice('reminderDays',v,l,reminder)).join('')}</div></section><label class="k-document-form-wide">Ссылка на файл<input name="fileUrl" type="url" placeholder="https://..."></label><label class="k-document-form-wide">Примечание<textarea name="note" rows="3" placeholder="Условия, серия, особые отметки"></textarea></label></div><button class="k-btn k-btn-primary" type="submit">Сохранить документ</button></form>`;}

  function documentCard(doc,vehicles){const state=documentState(doc);return `<article class="k-document-card k-document-card--${state.key}"><div class="k-document-card-head"><span>${esc(documentTypeLabel[doc.document_type]||'Документ')}</span><b>${state.label}</b></div><h2>${esc(doc.title||'Документ автомобиля')}</h2><p>${esc(vehicles[String(doc.vehicle_id)]||'Автомобиль')} · ${esc(doc.document_number||'Без номера')}</p>${doc.issuer_name?`<small>Выдан: ${esc(doc.issuer_name)}</small>`:''}<div><small>Дата выдачи: ${esc(doc.issued_at||'—')}</small><small>Срок: ${esc(doc.expires_at||'Без срока')}</small></div>${doc.note?`<p class="k-document-note">${esc(doc.note)}</p>`:''}<div class="k-document-actions">${doc.file_url?`<a class="k-btn" href="${esc(doc.file_url)}" target="_blank" rel="noopener">Открыть файл</a>`:''}<button class="k-btn k-btn-danger" type="button" data-document-delete="${esc(doc.id)}">Удалить</button></div></article>`;}
  async function mountDocuments(){if(!isClientCabinetRole())return;if(currentRole()==='client'||currentRole()==='admin'||currentRole()==='owner'){openClientAccountWindow('documents');return;}try{const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;const vehicles=Object.fromEntries((d.vehicles||[]).map(v=>[String(v.id),v.title||[v.brand,v.model].filter(Boolean).join(' ')]));const docs=d.documents||[];const rows=docs.map(doc=>documentCard(doc,vehicles)).join('')||'<div class="k-empty-card"><h2>Документов пока нет</h2><p>Добавьте первый документ и укажите срок действия — приложение напомнит заранее.</p></div>';const expired=docs.filter(x=>documentState(x).key==='expired').length,soon=docs.filter(x=>documentState(x).key==='soon').length;replace(shell('Документы',`Всего ${docs.length}. Просрочено: ${expired}. Скоро истекают: ${soon}.`,`${documentForm(d)}<div class="k-document-summary"><span><b>${docs.length}</b><small>в архиве</small></span><span><b>${soon}</b><small>скоро истекают</small></span><span><b>${expired}</b><small>просрочено</small></span></div><div class="k-document-grid">${rows}</div>`));const root=document.querySelector('#k-page-outlet .k-client-cabinet-page');root?.addEventListener('submit',async ev=>{const form=ev.target;if(!(form instanceof HTMLFormElement)||form.id!=='k-client-document-form')return;ev.preventDefault();const payload=Object.fromEntries(new FormData(form).entries());const r=await api.saveDocument(payload);if(!r.ok){window.KaretaToast?.error(r.payload?.message||'Не удалось сохранить документ');return;}window.KaretaApiClient.invalidate('client.cabinet');data=null;window.KaretaToast?.success('Документ сохранён');await mountDocuments();});root?.addEventListener('click',async ev=>{const choice=ev.target.closest('[data-cabinet-doc-choice]');if(choice){const form=choice.closest('form'),name=choice.dataset.cabinetDocChoice,hidden=form?.querySelector(`input[type=\"hidden\"][name=\"${name}\"]`);if(hidden)hidden.value=choice.dataset.value||'';form?.querySelectorAll(`[data-cabinet-doc-choice=\"${name}\"]`).forEach(node=>node.classList.toggle('is-active',node===choice));return;}const b=ev.target.closest('[data-document-delete]');if(!b)return;const r=await api.deleteDocument(b.dataset.documentDelete);if(!r.ok){window.KaretaToast?.error(r.payload?.message||'Не удалось удалить документ');return;}window.KaretaApiClient.invalidate('client.cabinet');data=null;window.KaretaToast?.success('Документ удалён');await mountDocuments();});}catch(e){if(e.message==='session_changed')return;replace(shell('Документы','',`<div class="k-empty-card">${esc(e.message)}</div>`));}}
  async function mountPromos(){if(!isClientCabinetRole())return;try{const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;const rows=(d.promotions||[]).map(p=>`<article class="k-promo-card"><span>${esc(p.badge||'Предложение')}</span><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><a class="k-btn k-btn-primary" href="${esc(p.action_url||'#/services')}">${esc(p.action_label||'Открыть')}</a></article>`).join('')||'<div class="k-empty-card">Новых акций пока нет.</div>';replace(shell('Мои акции','Персональные предложения и полезные возможности.',`<div class="k-promo-grid">${rows}</div>`));}catch(e){if(e.message==='session_changed')return;replace(shell('Мои акции','',`<div class="k-empty-card">${esc(e.message)}</div>`));}}
  function moreLayoutPicker(){
    return `<section class="k-more-layout-settings k-more-layout-settings--fixed"><input type="hidden" name="more_menu_layout" value="honeycomb"><div class="k-more-layout-fixed-preview" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><b></b></div><div><b>Меню «Ещё» — соты KARETA</b><small>Единый вариант интерфейса: профиль, быстрый доступ и поддержка. Старые полукруг/сетка удалены.</small></div></section>`;
  }

  function renderTariff(){
    const role=currentRole();
    if(!['client','master'].includes(role))return `<section class="k-page k-client-cabinet-page"><div class="k-empty-card"><h1>Тариф</h1><p>Тарифные планы этого этапа доступны для Клиента и Мастера.</p><a class="k-btn k-btn-primary" href="#/cabinet">Вернуться в кабинет</a></div></section>`;
    return shell('Тариф','Возможности и лимиты текущего типа аккаунта.',`<div id="k-tariff-host" class="k-tariff-host" aria-live="polite"><div class="k-cabinet-loading">Загрузка тарифа…</div></div>`);
  }
  function tariffMoney(value,isPaid=false){if(!isPaid&&(value===0||value==='0'))return 'Бесплатно';if(isPaid&&(value===null||value===undefined||value===''))return 'Платный тариф';if(value===0||value==='0')return isPaid?'Цена настраивается':'Бесплатно';return money(value)+'/мес.';}
  function tariffMetric(title,used,limit,note=''){
    const u=Math.max(0,Number(used||0)),l=Math.max(0,Number(limit||0)),pct=l>0?Math.min(100,Math.round(u*100/l)):0,full=l>0&&u>=l;
    return `<article class="k-tariff-metric ${full?'is-full':''}"><div><span>${esc(title)}</span><b>${u} / ${l||'∞'}</b></div><div class="k-tariff-meter"><i style="width:${pct}%"></i></div>${note?`<small>${esc(note)}</small>`:''}</article>`;
  }
  function tariffPlanCard(plan,currentCode){
    const current=String(plan?.code||'')===String(currentCode||'');const features=Object.values(plan?.features||{});
    return `<article class="k-tariff-plan ${current?'is-current':''}"><header><div><span>${current?'ТЕКУЩИЙ ПЛАН':'ДОСТУПНЫЙ ПЛАН'}</span><h3>${esc(plan?.name||'Тариф')}</h3></div><b>${esc(tariffMoney(plan?.monthlyPrice,!!plan?.isPaid))}</b></header><p>${esc(plan?.description||'')}</p><ul>${features.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>${current?'<em>Активен для текущего типа аккаунта</em>':(plan?.isPaid?'<em>KARETA PRO — платный тариф. Подключение выполняется через управление аккаунтом.</em>':'<em>Обычный тариф текущего типа аккаунта.</em>')}</article>`;
  }
  async function mountTariff(){
    const role=currentRole();if(role==='client'||role==='admin'||role==='owner'){openClientAccountWindow('tariff');return;}
    const host=document.querySelector('#k-tariff-host');if(!host)return;if(!['client','master'].includes(role))return;
    try{
      const response=await window.KaretaApiClient.request('api/db.php?action=tariffs.getMine',{method:'GET',cacheTtlMs:0});if(!response.ok)throw new Error(response.payload?.message||response.payload?.error||'Не удалось загрузить тариф');
      const d=response.payload?.data||{},limits=d.limits||{},usage=d.usage||{},current=d.current||{},plans=Array.isArray(d.plans)?d.plans:[];
      const metrics=role==='master' ? [
        tariffMetric('Принято заявок сегодня',usage.acceptedRequestsToday,limits.acceptedRequestsPerDay,'Счётчик новых принятий сбрасывается на следующий день.'),
        tariffMetric('Активные приёмы на выбранный день',usage.activeIntakesOnDate,limits.activeIntakesPerDay,'На один день нельзя запланировать больше лимита приёмов.'),
        tariffMetric('Незакрытые машины в ремонте',usage.openRepairs,limits.openRepairs,'При достижении лимита новые назначения блокируются до закрытия ремонта.')
      ] : [
        tariffMetric('Активные заявки',usage.activeRequests,limits.activeRequests,'Завершённые и отменённые заявки лимит не занимают.'),
        tariffMetric('Автомобили в гараже',usage.vehicles,limits.vehicles,'Архивный автомобиль не занимает активный лимит.')
      ];
      const rule=role==='master'?`<aside class="k-tariff-rule"><b>Как работает ограничение Мастера</b><p>Дневные лимиты и общий лимит ремонтов проверяются одновременно. Если открыто ${Number(limits.openRepairs||0)} из ${Number(limits.openRepairs||0)} ремонтов, новая машина не принимается даже в новый день — сначала нужно закрыть хотя бы один текущий ремонт.</p></aside>`:'';
      host.innerHTML=`<section class="k-tariff-current"><header><div><span>ТЕКУЩИЙ ТАРИФ</span><h2>${esc(current.name||'—')}</h2><p>${esc(current.description||'')}</p></div><strong>${esc(tariffMoney(current.monthlyPrice,!!current.isPaid))}</strong></header><div class="k-tariff-metrics">${metrics.join('')}</div>${rule}</section><section class="k-tariff-plans"><header><span>ПЛАНЫ ДЛЯ ${role==='master'?'МАСТЕРА':'КЛИЕНТА'}</span><h2>Сравнение возможностей</h2></header><div class="k-tariff-plan-grid">${plans.map(p=>tariffPlanCard(p,current.code)).join('')}</div></section>`;
    }catch(error){host.innerHTML=`<div class="k-empty-card"><h2>Тариф временно недоступен</h2><p>${esc(error?.message||'Ошибка загрузки')}</p></div>`;}
  }
  function renderStaffSettings(value){const selected=value||window.KaretaSmartActionHub?.snapshot?.().layout||'honeycomb';return shell('Настройки','Настройте дополнительное меню для текущего рабочего аккаунта.',`<form id="k-staff-settings-form" class="k-settings-form">${moreLayoutPicker(selected)}<button class="k-btn k-btn-primary" type="submit">Сохранить настройки</button><output id="k-settings-status"></output></form>`);}
  function masterWorkplaceSettings(preferences={}){
    const windows={status:true,attention:true,nextOrder:true,newAccepted:true,todayQueue:true,upcoming:true,...(preferences.windows||{}),quickActions:false,exchange:false};
    const params={exchangeLimit:6,upcomingLimit:6,autoRefreshSec:60,compactCards:false,...(preferences.params||{})};
    const windowRows=[
      ['status','Статус смены','Свободен, занят, обед или выходной.'],
      ['attention','Требует решения','Заказы, где нужен ответ, согласование или запчасть.'],
      ['nextOrder','Следующая машина','Ближайший автомобиль и быстрый запуск работы.'],
      ['newAccepted','Новые принятые','Принятые клиентом отклики, SLA ответа, запись и быстрый переход в чат.'],
      ['todayQueue','Очередь сегодня','Все машины текущего дня.'],
      ['upcoming','Ближайшие записи','Будущие записи и переход в календарь.'],
    ];
    const radio=(name,value,label,current)=>`<label class="k-master-param-choice"><input type="radio" name="${name}" value="${value}" ${String(current)===String(value)?'checked':''}><span>${label}</span></label>`;
    return `<fieldset class="k-master-workplace-settings"><legend>Окна рабочего места</legend><p>Выберите, какие рабочие окна показывать на странице Мастера. Настройка сохраняется только для текущего мастер-профиля.</p><div class="k-master-window-options">${windowRows.map(([key,title,text])=>`<label class="k-setting-row k-master-window-row"><span><b>${title}</b><small>${text}</small></span><input type="checkbox" name="master_window_${key}" ${windows[key]!==false?'checked':''}><i></i></label>`).join('')}</div><div class="k-master-workplace-params"><section><h3>Заявки в Бирже</h3><div class="k-master-param-options">${[3,6,9,12].map(v=>radio('master_exchange_limit',v,`${v} заявок`,params.exchangeLimit)).join('')}</div></section><section><h3>Ближайшие записи</h3><div class="k-master-param-options">${[3,6,9,12].map(v=>radio('master_upcoming_limit',v,`${v} записей`,params.upcomingLimit)).join('')}</div></section><section><h3>Автообновление</h3><div class="k-master-param-options">${[[0,'Выкл.'],[30,'30 сек'],[60,'1 мин'],[120,'2 мин'],[300,'5 мин']].map(([v,l])=>radio('master_refresh_sec',v,l,params.autoRefreshSec)).join('')}</div></section>${toggle('master_compact_cards','Компактные карточки','Уменьшить вертикальные отступы на рабочем экране.',params.compactCards)}</div></fieldset>`;
  }
  function collectMasterWorkplaceSettings(form){
    const windows={quickActions:false,exchange:false};['status','attention','nextOrder','newAccepted','todayQueue','upcoming'].forEach(key=>windows[key]=form.querySelector(`[name="master_window_${key}"]`)?.checked===true);
    return {windows,params:{exchangeLimit:Number(form.querySelector('[name="master_exchange_limit"]:checked')?.value||6),upcomingLimit:Number(form.querySelector('[name="master_upcoming_limit"]:checked')?.value||6),autoRefreshSec:Number(form.querySelector('[name="master_refresh_sec"]:checked')?.value||60),compactCards:form.querySelector('[name="master_compact_cards"]')?.checked===true}};
  }
  async function mountSettings(){
    const role=currentRole();
    if(role==='client'||role==='admin'||role==='owner'){openClientAccountWindow('interface');return;}
    if(role==='master'){
      try{
        await window.KaretaSmartActionHub?.loadPreference?.();
        if(!window.KaretaMasterWorkplaceApi){
          const routeLoader=window.KaretaRouteAssetLoader;
          if(routeLoader?.isKnownLazy?.('masterWorkplaceSettings'))await routeLoader.ensureRoute('masterWorkplaceSettings');
        }
        const workplaceApi=window.KaretaMasterWorkplaceApi;
        if(!workplaceApi)throw new Error('Модуль настроек рабочего места не загружен');
        const response=await workplaceApi.get(window.KaretaApiClient,{force:true,cacheTtlMs:0});
        if(!response.ok)throw new Error(response.payload?.message||response.payload?.error||'Не удалось загрузить настройки рабочего места');
        const preferences=response.payload?.data?.preferences||{};
        const selected=window.KaretaSmartActionHub?.snapshot?.().layout||'honeycomb';
        replace(shell('Настройки рабочего места','Настройте свои окна, количество заявок, автообновление и дополнительное меню Мастера.',`<form id="k-master-settings-form" class="k-settings-form">${masterWorkplaceSettings(preferences)}${moreLayoutPicker(selected)}<div class="k-master-settings-links"><a class="k-btn k-btn-secondary" href="#/services/manage">Мои услуги</a><a class="k-btn k-btn-secondary" href="#/master">Посмотреть рабочее место</a></div><button class="k-btn k-btn-primary" type="submit">Сохранить настройки</button><output id="k-settings-status"></output></form><div data-messaging-settings-host></div>`));
        window.KaretaMessagingSettings?.mount?.(document.querySelector('[data-messaging-settings-host]'));
        document.querySelector('#k-master-settings-form')?.addEventListener('submit',async ev=>{
          ev.preventDefault();const form=ev.currentTarget;const out=document.querySelector('#k-settings-status');const save=form.querySelector('[type="submit"]');if(save)save.disabled=true;out.textContent='Сохранение…';
          try{
            const payload=collectMasterWorkplaceSettings(form);const result=await workplaceApi.savePreferences(window.KaretaApiClient,payload);if(!result.ok)throw new Error(result.payload?.message||result.payload?.error||'Ошибка сохранения');
            const layout=form.querySelector('input[name=more_menu_layout]')?.value||'honeycomb';await window.KaretaSmartActionHub?.savePreference?.(layout);out.textContent='Настройки рабочего места сохранены';window.KaretaToast?.success('Настройки рабочего места сохранены');
          }catch(error){out.textContent=error?.message||'Ошибка сохранения';window.KaretaToast?.error(out.textContent);}finally{if(save)save.disabled=false;}
        });
      }catch(e){if(e.message==='session_changed')return;replace(shell('Настройки рабочего места','',`<div class="k-empty-card">${esc(e.message)}</div>`));}
      return;
    }
    if(!isClientCabinetRole()){
      try{
        await window.KaretaSmartActionHub?.loadPreference?.();
        replace(renderStaffSettings(window.KaretaSmartActionHub?.snapshot?.().layout||'honeycomb'));
        document.querySelector('#k-staff-settings-form')?.addEventListener('submit',async ev=>{
          ev.preventDefault();const value=ev.currentTarget.querySelector('input[name=more_menu_layout]')?.value||'honeycomb';const out=document.querySelector('#k-settings-status');out.textContent='Сохранение…';await window.KaretaSmartActionHub?.savePreference?.(value);out.textContent='Настройки сохранены';window.KaretaToast?.success('Настройки сохранены');
        });
      }catch(e){if(e.message==='session_changed')return;replace(shell('Настройки','',`<div class="k-empty-card">${esc(e.message)}</div>`));}
      return;
    }
    try{
      const epoch=sessionEpoch,d=await load();if(epoch!==sessionEpoch)return;const p=d.preferences||{};
      await window.KaretaSmartActionHub?.loadPreference?.();
      if(epoch!==sessionEpoch)return;
      const selectedLayout=window.KaretaSmartActionHub?.snapshot?.().layout||p.more_menu_layout||'honeycomb';
      replace(shell('Настройки','Выберите уведомления и внешний вид дополнительного меню.',`<form id="k-client-settings-form" class="k-settings-form">${toggle('notify_orders','Статусы заказов','Изменения этапов, стоимости и готовности',p.notify_orders)}${toggle('notify_service','Напоминания по автомобилю','ТО, рекомендации и сервисные сроки',p.notify_service)}${toggle('notify_promotions','Акции','Персональные предложения и скидки',p.notify_promotions)}${toggle('compact_mobile','Компактный мобильный режим','Скрывать повторяющиеся поясняющие блоки',p.compact_mobile)}${moreLayoutPicker(selectedLayout)}<button class="k-btn k-btn-primary" type="submit">Сохранить настройки</button><output id="k-settings-status"></output></form>`));
      document.querySelector('#k-client-settings-form')?.addEventListener('submit',async ev=>{
        ev.preventDefault();const payload={};ev.currentTarget.querySelectorAll('input[type=checkbox]').forEach(i=>payload[i.name]=i.checked);payload.more_menu_layout=ev.currentTarget.querySelector('input[name=more_menu_layout]')?.value||'honeycomb';const out=document.querySelector('#k-settings-status');out.textContent='Сохранение…';const r=await api.savePreferences(payload);out.textContent=r.ok?'Настройки сохранены':(r.payload?.message||'Ошибка сохранения');if(r.ok){document.documentElement.classList.toggle('k-compact-mobile',payload.compact_mobile);await window.KaretaSmartActionHub?.savePreference?.(payload.more_menu_layout);window.KaretaApiClient.invalidate('client.cabinet');data=null;window.KaretaToast?.success('Настройки сохранены');}else{window.KaretaToast?.error(out.textContent);}
      });
    }catch(e){if(e.message==='session_changed')return;replace(shell('Настройки','',`<div class="k-empty-card">${esc(e.message)}</div>`));}
  }
  function toggle(name,title,text,value){return `<label class="k-setting-row"><span><b>${title}</b><small>${text}</small></span><input type="checkbox" name="${name}" ${Number(value)!==0?'checked':''}><i></i></label>`;}
  window.addEventListener('kareta:session-anonymous',()=>{sessionEpoch++;data=null;serviceVehicleId='';});
  window.KaretaCabinetPages=Object.freeze({renderCabinet,renderGarage,renderData,renderHistory,renderDocuments,renderPromos,renderTariff,renderSettings,mountCabinet,mountGarage,mountData,mountHistory,mountDocuments,mountPromos,mountTariff,mountSettings,refreshClientCabinet:async()=>{data=null;await mountCabinet();}});
})();
